package sv.edu.ues.vl23003.saldo.ui.movement; import android.os.Bundle; import androidx.appcompat.app.AppCompatActivity; import sv.edu.ues.vl23003.saldo.R; import sv.edu.ues.vl23003.saldo.data.local.entity.MovementEntity; import sv.edu.ues.vl23003.saldo.data.repository.MovementRepository; public class MovementFormActivity extends AppCompatActivity {protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_movement_form);findViewById(R.id.btn_save_movement).setOnClickListener(v->{MovementEntity m=new MovementEntity();new MovementRepository(this).saveLocal(m);finish();});}}
